// ENG-2410 proof: layout width, placeholder fit, scope-icon cursor, search flash timing.
import path from "node:path";

const PHASE = process.env.ENG2410_PHASE || "run";

const settingsDialog = (page) =>
  page.locator(".bp3-dialog").filter({ has: page.locator(".dg-settings-tabs") }).last();

export default {
  async ready({ page }) {
    return page.locator(".dg-settings-tabs").first().isVisible();
  },
  async run({ page, outDir }) {
    const shot = (name) => path.join(outDir, `eng2410-${PHASE}-${name}.png`);
    await page.setViewportSize({ width: 1920, height: 1080 });
    await page.waitForTimeout(500);
    const dialog = settingsDialog(page);
    await dialog.locator(".bp3-tab", { hasText: /^General$/ }).first().click();
    const row = dialog.locator(".dg-setting-row", { hasText: "Personal override" }).first();
    await row.waitFor();
    await row.scrollIntoViewIfNeeded();
    await page.mouse.move(5, 5);
    await page.waitForTimeout(300);

    // 1. Layout: gap between the label column and the trailing control.
    const layout = await row.evaluate((el) => {
      const label = el.firstElementChild.querySelector("span:last-child").getBoundingClientRect();
      const control = el.lastElementChild.getBoundingClientRect();
      const panel = el.closest(".bp3-tab-panel").getBoundingClientRect();
      return {
        panelWidth: Math.round(panel.width),
        rowWidth: Math.round(el.getBoundingClientRect().width),
        labelRight: Math.round(label.right),
        controlLeft: Math.round(control.left),
        labelToControlGap: Math.round(control.left - label.right),
      };
    });
    await dialog.screenshot({ path: shot("1-layout") });

    // 2. Placeholder: text overflow inside the keycap input.
    const input = row.locator("input").first();
    const placeholder = await input.evaluate((el) => ({
      text: el.placeholder,
      value: el.value,
      clientWidth: el.clientWidth,
      scrollWidth: el.scrollWidth,
      textWidth: (() => {
        const cs = getComputedStyle(el);
        const ctx = document.createElement("canvas").getContext("2d");
        ctx.font = `${cs.fontSize} ${cs.fontFamily}`;
        return Math.round(ctx.measureText(el.placeholder).width);
      })(),
      contentWidth: (() => {
        const cs = getComputedStyle(el);
        return Math.round(el.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight));
      })(),
    }));
    placeholder.fits = placeholder.textWidth <= placeholder.contentWidth;
    await row.screenshot({ path: shot("2-placeholder") });

    // 3. Scope icon cursor, with the tooltip open.
    const scope = row.locator(".dg-setting-row__scope").first();
    await scope.hover();
    await page.waitForTimeout(700);
    const cursor = await scope.evaluate((el) => getComputedStyle(el).cursor);
    await row.screenshot({ path: shot("3-tooltip"), animations: "disabled" });
    const tooltip = await page.locator(".bp3-tooltip").first().isVisible().catch(() => false);
    await page.mouse.move(5, 5);

    // 4. Search flash: record how long the fill class stays on the target row.
    const search = dialog.locator("input[placeholder='Search settings']");
    await search.click();
    await search.fill("Canvas Page Format");
    await page.waitForTimeout(400);
    await page.locator(".bp3-menu-item", { hasText: "Canvas Page Format" }).first().click();
    const timeline = page.evaluate(
      () =>
        new Promise((resolve) => {
          const start = performance.now();
          let fillOn = null;
          let fillOff = null;
          let fillClass = null;
          let color = null;
          const tick = () => {
            const t = performance.now() - start;
            const el = document.querySelector(".-mx-2.rounded.transition-colors, .bg-gray-100.-mx-2, .bg-gray-200.-mx-2");
            const fill = document.querySelector("[data-setting-id].bg-gray-100, [data-setting-id].bg-gray-200");
            if (fill && fillOn === null) {
              fillOn = t;
              fillClass = fill.classList.contains("bg-gray-200") ? "bg-gray-200" : "bg-gray-100";
              color = getComputedStyle(fill).backgroundColor;
            }
            if (!fill && fillOn !== null && fillOff === null) fillOff = t;
            if (t > 3000 || (fillOff !== null && !el)) {
              resolve({ fillOn: Math.round(fillOn), fillOff: Math.round(fillOff), holdMs: Math.round(fillOff - fillOn), fillClass, color });
              return;
            }
            requestAnimationFrame(tick);
          };
          tick();
        }),
    );
    await page.waitForTimeout(450);
    await dialog.screenshot({ path: shot("4-flash-450ms") });
    const flash = await timeline;

    return { phase: PHASE, layout, placeholder, scope: { cursor, tooltip }, flash };
  },
};

